% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
K          = [4, -1; -1, 3]; % [Input] (N/m) Stiffness
F          = [1; 2]; % [Input] (N) Load
a          = [1; 2; 3]; % [Input] (m) a
b          = [4; 5; 6]; % [Input] (m) b
M          = [0, 1; -1, 0]; % [Input] (1/s) Rotation
y          = [1; 0]; % [State] (1) State
c          = [4; 9]; % [Input] (1) Squares

%% Stage 1
% [IMPLICIT] Stiffness system: \mathbf{K}\mathbf{u} = \mathbf{F}
% Newton–Raphson on the residual (left side - right side) = 0, solved for u
% Linear in u: solved directly
u = K \ (F);
% [EXPLICIT] Inverse solve: \mathbf{r} = \mathbf{K}^{-1}\mathbf{F}
r = (K \ F);
% [EXPLICIT] Cross product: \mathbf{w} = \mathbf{a} \times \mathbf{b}
w = cross(a, b);
% [EXPLICIT] Dot product: s = \mathbf{a} \cdot \mathbf{b}
s = dot(a, b);
% [EXPLICIT] Norm: n_a = \|\mathbf{a}\|
n_a = norm(a);
% --- ODE system: y over t: RK4, 50 steps ---
% Rotation ODE: \frac{d\mathbf{y}}{dt} = \mathbf{M}\mathbf{y}
t = 0;
h_rk = (1 - t) / 50;
w_rk = [1, 2, 2, 1]; c_rk = [0.5, 0.5, 1];
for step = 1:50
    t_rk0 = t;
    y_rk0 = y; y_acc = 0;
    for stage = 1:4
        y_rate = M * y;
        y_acc = y_acc + w_rk(stage) * y_rate;
        if stage < 4
            t = t_rk0 + c_rk(stage) * h_rk;
            y = y_rk0 + c_rk(stage) * h_rk * y_rate;
        end
    end
    t = t_rk0 + h_rk;
    y = y_rk0 + h_rk / 6 * y_acc;
end
% [IMPLICIT] Nonlinear vector root: \mathbf{z} \odot \mathbf{z} = \mathbf{c}
% Newton–Raphson on the residual (left side - right side) = 0, solved for z
res_z = @(z) z .* z - c;
z = 1 * ones(2, 1); % initial guess
converged = false;
for it = 1:50
    r_nr = res_z(z);
    jac_nr = zeros(numel(r_nr), numel(z));
    for j_nr = 1:numel(z)
        e_nr = zeros(size(z)); e_nr(j_nr) = 1e-6 * max(abs(z(j_nr)), 1e-6);
        jac_nr(:, j_nr) = (res_z(z + e_nr) - res_z(z - e_nr)) / (2 * e_nr(j_nr));
    end
    z_new = z - jac_nr \ r_nr;
    if max(abs(z_new - z)) < 1e-12 * (1 + max(abs(z))), z = z_new; converged = true; break; end
    z = z_new;
end
if ~converged, warning('z did not converge in %d iterations', 50); end
% [EXPLICIT] Gram matrix: \mathbf{P} = \mathbf{K}\mathbf{K}^T
P = K * K.';

%% Stage 2
% [EXPLICIT] Strain energy: E = \frac{1}{2}\mathbf{u}^T\mathbf{K}\mathbf{u}
E = dot(1 / 2 * u.' * K, u);
% [EXPLICIT] Combination: \mathbf{q} = 2 \mathbf{r} + \mathbf{u}
q_ = 2 * r + u;

%% Results
fprintf('%-12s = %s\n', 'K', mat2str(K));
fprintf('%-12s = %s\n', 'F', mat2str(F));
fprintf('%-12s = %s\n', 'u', mat2str(u));
fprintf('%-12s = %s\n', 'E', mat2str(E));
fprintf('%-12s = %s\n', 'r', mat2str(r));
fprintf('%-12s = %s\n', 'a', mat2str(a));
fprintf('%-12s = %s\n', 'b', mat2str(b));
fprintf('%-12s = %s\n', 'w', mat2str(w));
fprintf('%-12s = %s\n', 's', mat2str(s));
fprintf('%-12s = %s\n', 'n_a', mat2str(n_a));
fprintf('%-12s = %s\n', 'M', mat2str(M));
fprintf('%-12s = %s\n', 'y', mat2str(y));
fprintf('%-12s = %s\n', 't', mat2str(t));
fprintf('%-12s = %s\n', 'c', mat2str(c));
fprintf('%-12s = %s\n', 'z', mat2str(z));
fprintf('%-12s = %s\n', 'P', mat2str(P));
fprintf('%-12s = %s\n', 'q_', mat2str(q_));